package com.blackice.bc1;

import android.graphics.*;
import android.view.*;
import android.widget.*;
import com.blackice.bc1.editor.*;
import java.util.*;

/** Fill controls use the same project snapshot/undo transaction as transform gestures. */
final class FillPanel {
 final EditorActivity a;String owner,stopId,activeEasing="Fill color and alpha";FillStyle draft;boolean updating,dragging;
 final List<Runnable> easingGroups=new ArrayList<>();String renderedStop;
 void save(android.os.Bundle state){state.putString("fill-stop",stopId);state.putString("fill-easing-property",activeEasing);}
 void restore(android.os.Bundle state){if(state!=null){stopId=state.getString("fill-stop");activeEasing=state.getString("fill-easing-property","Fill color and alpha");}}
 Wheel wheel;Ramp ramp;View swatch;EditText hex,rgba;TextView activeLabel,colorKey,positionKey,angleKey,previous,next;
 SeekBar value,alpha,position,angle;TextView valueLabel,alphaLabel,positionLabel,angleLabel;
 FillPanel(EditorActivity a){this.a=a;}
 long time(){return Math.max(0,a.project.playheadMs-a.overlay().startMs);}
 FillStyle style(){return a.overlay().fill==null?draft:a.overlay().fill;}
 FillStyle.Track color(){return style().gradient?style().stops.get(stopId).color:style().solid;}
 void ensure(){if(a.overlay().fill==null)a.overlay().fill=draft;}
 boolean visible(){return a.overlay()!=null&&a.overlay().id.equals(owner)&&a.panels.showing()&&"Color & Fill".equals(a.panels.title());}
 void commit(String message,Runnable change){if(!a.layerEditable())return;a.pausePlayback();a.edit(message,()->{ensure();change.run();});}
 void begin(){if(!a.layerEditable())return;a.pausePlayback();a.beginLiveAdjust();dragging=true;}
 void live(Runnable change){if(!dragging)return;a.liveAdjust(()->{ensure();change.run();});refresh();}
 void end(boolean cancel){if(!dragging)return;dragging=false;if(cancel)a.cancelLiveAdjust();else a.endLiveAdjust("Fill updated",()->{});refresh();}
 TextView button(String title,Runnable action){return a.button(title,v->action.run());}
 void build(LinearLayout into){
  easingGroups.clear();
  owner=a.overlay().id;draft=a.overlay().fill==null?new FillStyle(a.overlay().color):a.overlay().fill;List<String> ids=style().ids(time());if(!ids.contains(stopId))stopId=ids.get(0);renderedStop=stopId;
  LinearLayout modes=a.row();for(boolean gradient:new boolean[]{false,true}){TextView b=button(gradient?"Linear gradient":"Solid color",()->commit("Fill mode updated",()->style().gradient=gradient));b.setSelected(style().gradient==gradient);b.setTextColor(style().gradient==gradient?EditorActivity.CYAN:EditorActivity.TEXT);modes.addView(b,new LinearLayout.LayoutParams(0,a.dp(48),1));}into.addView(modes);
  LinearLayout navigation=a.row();previous=button("‹ Previous Key",()->jump(false));next=button("Next Key ›",()->jump(true));navigation.addView(previous,new LinearLayout.LayoutParams(0,a.dp(48),1));navigation.addView(next,new LinearLayout.LayoutParams(0,a.dp(48),1));into.addView(navigation);
  ramp=null;position=null;positionKey=null;angle=null;angleKey=null;
  if(style().gradient){
   activeLabel=a.note("");into.addView(activeLabel);ramp=new Ramp();into.addView(ramp,new LinearLayout.LayoutParams(-1,a.dp(72)));
   LinearLayout actions=a.row();actions.addView(button("+ Stop",()->commit("Gradient stop added",()->stopId=style().add(time(),.5,(int)color().at(time())))),new LinearLayout.LayoutParams(0,a.dp(48),1));actions.addView(button("Remove stop",()->{if(style().ids(time()).size()<=2){a.tell("Keep at least two gradient stops.");return;}commit("Gradient stop removed",()->{style().remove(time(),stopId);stopId=style().ids(time()).get(0);});}),new LinearLayout.LayoutParams(0,a.dp(48),1));into.addView(actions);
   LinearLayout pos=a.row();positionLabel=a.note("Stop position");pos.addView(positionLabel,new LinearLayout.LayoutParams(0,a.dp(48),1));positionKey=diamond("Stop position",()->style().stops.get(stopId).position);pos.addView(positionKey,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));pos.addView(button("Set",()->number("Stop position (%)",style().stops.get(stopId).position,100,0,100)),new LinearLayout.LayoutParams(a.dp(52),a.dp(48)));into.addView(pos);easing(into,"Stop position",()->style().stops.get(stopId).position);position=slider(into,"Gradient stop position",1000,p->style().stops.get(stopId).position.set(time(),p/1000d));
   LinearLayout dir=a.row();angleLabel=a.note("Direction");dir.addView(angleLabel,new LinearLayout.LayoutParams(0,a.dp(48),1));angleKey=diamond("Gradient direction",()->style().angle);dir.addView(angleKey,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));dir.addView(button("Set",()->number("Gradient angle (degrees)",style().angle,1,-360000,360000)),new LinearLayout.LayoutParams(a.dp(52),a.dp(48)));into.addView(dir);easing(into,"Gradient direction",()->style().angle);angle=slider(into,"Gradient direction",3600,p->style().angle.set(time(),p/10d));
  }else activeLabel=null;
  LinearLayout heading=a.row();heading.addView(a.label(style().gradient?"Selected stop color":"Fill color",14,EditorActivity.TEXT,true),new LinearLayout.LayoutParams(0,a.dp(48),1));colorKey=diamond("Fill color and alpha",this::color);heading.addView(colorKey,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));into.addView(heading);easing(into,"Fill color and alpha",this::color);
  wheel=new Wheel();into.addView(wheel,new LinearLayout.LayoutParams(-1,a.dp(190)));
  valueLabel=a.note("Brightness");into.addView(valueLabel);value=slider(into,"Fill brightness",1000,p->setHsv(-1,-1,p/1000f));
  alphaLabel=a.note("Fill alpha");into.addView(alphaLabel);alpha=slider(into,"Fill alpha",255,p->color().set(time(),((int)color().at(time())&0xFFFFFF)|(p<<24)));
  swatch=new View(a);swatch.setContentDescription("Current fill color swatch");into.addView(swatch,new LinearLayout.LayoutParams(-1,a.dp(36)));
  hex=a.field(into,"HEX #RRGGBBAA","");hex.setSingleLine();hex.setContentDescription("Fill HEX RRGGBBAA");into.addView(button("Apply HEX",()->{try{String text=hex.getText().toString().trim().replace("#","");if(!text.matches("[0-9a-fA-F]{6}([0-9a-fA-F]{2})?"))throw new IllegalArgumentException();long n=Long.parseLong(text,16);int c=text.length()==6?(int)n|0xFF000000:(int)((n>>>8)|((n&255)<<24));commit("Fill color updated",()->color().set(time(),c));}catch(IllegalArgumentException ex){hex.setError("Use #RRGGBB or #RRGGBBAA");}}));
  rgba=a.field(into,"RGBA (0–255, comma separated)","");rgba.setSingleLine();rgba.setContentDescription("Fill RGBA values");into.addView(button("Apply RGBA",()->{try{String[] parts=rgba.getText().toString().split(",");if(parts.length!=4)throw new IllegalArgumentException();int[] channels=new int[4];for(int i=0;i<4;i++){channels[i]=Integer.parseInt(parts[i].trim());if(channels[i]<0||channels[i]>255)throw new IllegalArgumentException();}int c=Color.argb(channels[3],channels[0],channels[1],channels[2]);commit("Fill color updated",()->color().set(time(),c));}catch(IllegalArgumentException ex){rgba.setError("Enter R, G, B, A; each 0–255");}}));
  into.addView(a.note("Fill alpha multiplies layer opacity. Each diamond animates its own property. Stop additions and removals hold until their saved time."));refresh();
 }
 interface TrackSource{FillStyle.Track get();}
 TextView diamond(String name,TrackSource source){TextView b=button("◇",()->commit(name+" keyframe",()->{source.get().toggle(time());activeEasing=name;a.easingControls.selectFill(easingScope(name),source.get(),time());}));b.setContentDescription(name+" keyframe");return b;}
 String easingScope(String title){return title+(title.equals("Gradient direction")||!style().gradient?"":":"+stopId);}
 void easing(LinearLayout into,String title,TrackSource source){LinearLayout group=a.column();into.addView(group);Runnable render=()->{group.removeAllViews();a.easingControls.buildFill(group,title,easingScope(title),source::get,()->activeEasing=title);};easingGroups.add(render);render.run();}
 FillStyle.Track activeTrack(){if(!style().gradient)return color();return activeEasing.equals("Gradient direction")?style().angle:activeEasing.equals("Stop position")?style().stops.get(stopId).position:color();}
 interface SliderAction{void set(int value);}
 SeekBar slider(LinearLayout into,String name,int max,SliderAction action){SeekBar s=new SeekBar(a);s.setMax(max);s.setContentDescription(name);into.addView(s,new LinearLayout.LayoutParams(-1,a.dp(48)));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){begin();}public void onStopTrackingTouch(SeekBar bar){end(false);}public void onProgressChanged(SeekBar bar,int n,boolean user){if(!user||updating)return;if(dragging)live(()->action.set(n));else commit(name+" updated",()->action.set(n));}});s.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_CANCEL)end(true);return false;});return s;}
 void number(String title,FillStyle.Track track,double multiplier,double min,double max){a.numberDialog(title,String.format(Locale.ROOT,"%.2f",track.at(time())*multiplier),text->{double v=Double.parseDouble(text);if(!Double.isFinite(v)||v<min||v>max)throw new IllegalArgumentException("Use "+min+" to "+max);commit(title+" updated",()->track.set(time(),v/multiplier));});}
 void jump(boolean next){long key=style().neighbor(time(),next,a.panels.tolerance());if(key>=0){a.pausePlayback();a.seek(a.overlay().startMs+key);a.easingControls.selectFill(easingScope(activeEasing),activeTrack(),key);a.renderInspector();}}
 void key(TextView view,FillStyle.Track track){if(view==null)return;view.setText(track.keys.containsKey(time())?"◆":track.keys.isEmpty()?"◇":"◇·");view.setTextColor(track.keys.isEmpty()?EditorActivity.MUTED:EditorActivity.CYAN);}
 void refresh(){if(!visible()||wheel==null)return;FillStyle f=style();List<String> ids=f.ids(time());if(!ids.contains(stopId))stopId=ids.get(0);if(!Objects.equals(renderedStop,stopId)){renderedStop=stopId;for(Runnable render:easingGroups)render.run();}updating=true;int c=(int)color().at(time());float[] hsv=new float[3];Color.colorToHSV(c,hsv);value.setProgress(Math.round(hsv[2]*1000));alpha.setProgress(Color.alpha(c));valueLabel.setText(String.format(Locale.ROOT,"Brightness · %.1f%%",hsv[2]*100));alphaLabel.setText(String.format(Locale.ROOT,"Fill alpha · %.1f%%",Color.alpha(c)*100/255f));swatch.setBackgroundColor(c);if(!hex.hasFocus())hex.setText(String.format(Locale.ROOT,"#%06X%02X",c&0xFFFFFF,Color.alpha(c)));if(!rgba.hasFocus())rgba.setText(Color.red(c)+", "+Color.green(c)+", "+Color.blue(c)+", "+Color.alpha(c));key(colorKey,color());if(position!=null){FillStyle.Stop stop=f.stops.get(stopId);position.setProgress((int)Math.round(stop.position.at(time())*1000));positionLabel.setText(String.format(Locale.ROOT,"Position · %.1f%%",stop.position.at(time())*100));angle.setProgress((int)Math.round((f.angle.at(time())%360+360)%360*10));angleLabel.setText(String.format(Locale.ROOT,"Direction · %.1f°",f.angle.at(time())));activeLabel.setText("Selected stop "+(ids.indexOf(stopId)+1)+" of "+ids.size());key(positionKey,stop.position);key(angleKey,f.angle);ramp.invalidate();}EditorActivity.dim(previous,f.neighbor(time(),false,a.panels.tolerance())>=0);EditorActivity.dim(next,f.neighbor(time(),true,a.panels.tolerance())>=0);wheel.invalidate();updating=false;}
 void setHsv(float hue,float saturation,float brightness){int c=(int)color().at(time());float[] hsv=new float[3];Color.colorToHSV(c,hsv);if(hue>=0)hsv[0]=hue;if(saturation>=0)hsv[1]=saturation;if(brightness>=0)hsv[2]=brightness;color().set(time(),Color.HSVToColor(Color.alpha(c),hsv));}
 final class Wheel extends View {
  final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Wheel(){super(a);setFocusable(true);setContentDescription("Hue and saturation wheel. Arrow keys change hue and saturation; use HEX or RGBA for exact input.");}
  float radius(){return Math.max(1,Math.min(getWidth(),getHeight())/2f-a.dp(10));}
  @Override protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=radius();p.setShader(new SweepGradient(x,y,new int[]{Color.RED,Color.YELLOW,Color.GREEN,Color.CYAN,Color.BLUE,Color.MAGENTA,Color.RED},null));c.drawCircle(x,y,r,p);p.setShader(new RadialGradient(x,y,r,Color.WHITE,0x00FFFFFF,Shader.TileMode.CLAMP));c.drawCircle(x,y,r,p);p.setShader(null);float[] hsv=new float[3];Color.colorToHSV((int)color().at(time()),hsv);double angle=Math.toRadians(hsv[0]);float px=x+(float)Math.cos(angle)*r*hsv[1],py=y+(float)Math.sin(angle)*r*hsv[1];p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(4));p.setColor(Color.BLACK);c.drawCircle(px,py,a.dp(7),p);p.setStrokeWidth(a.dp(2));p.setColor(Color.WHITE);c.drawCircle(px,py,a.dp(7),p);p.setStyle(Paint.Style.FILL);}
  void point(float x,float y){float dx=x-getWidth()/2f,dy=y-getHeight()/2f;float hue=(float)((Math.toDegrees(Math.atan2(dy,dx))+360)%360),sat=Math.min(1,(float)Math.hypot(dx,dy)/radius());live(()->setHsv(hue,sat,-1));}
  @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){if(!a.layerEditable())return false;begin();getParent().requestDisallowInterceptTouchEvent(true);point(e.getX(),e.getY());return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){point(e.getX(),e.getY());return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);end(e.getActionMasked()==MotionEvent.ACTION_CANCEL);performClick();return true;}return false;}
  @Override public boolean onKeyDown(int key,KeyEvent e){float[] hsv=new float[3];Color.colorToHSV((int)color().at(time()),hsv);if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){commit("Fill hue updated",()->setHsv((hsv[0]+(key==KeyEvent.KEYCODE_DPAD_LEFT?359:1))%360,-1,-1));return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){commit("Fill saturation updated",()->setHsv(-1,Math.max(0,Math.min(1,hsv[1]+(key==KeyEvent.KEYCODE_DPAD_UP?.01f:-.01f))),-1));return true;}return super.onKeyDown(key,e);}
  @Override public boolean performClick(){super.performClick();return true;}
 }
 final class Ramp extends View {
  final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);boolean moving;float down;Ramp(){super(a);setFocusable(true);setContentDescription("Gradient ramp: select and drag a stop. Use Stop position for exact values.");}
  float x(double pos){return a.dp(14)+(getWidth()-a.dp(28))*(float)pos;}
  @Override protected void onDraw(Canvas c){List<FillStyle.Stop> stops=style().ordered(time());int[] colors=new int[stops.size()];float[] positions=new float[stops.size()];for(int i=0;i<stops.size();i++){colors[i]=(int)stops.get(i).color.at(time());positions[i]=(float)stops.get(i).position.at(time());}p.setShader(new LinearGradient(x(0),0,x(1),0,colors,positions,Shader.TileMode.CLAMP));c.drawRoundRect(x(0),a.dp(8),x(1),a.dp(36),a.dp(5),a.dp(5),p);p.setShader(null);for(FillStyle.Stop s:stops){p.setColor(s.id.equals(stopId)?EditorActivity.CYAN:EditorActivity.MUTED);c.drawCircle(x(s.position.at(time())),a.dp(48),a.dp(10),p);p.setColor((int)s.color.at(time()));c.drawCircle(x(s.position.at(time())),a.dp(48),a.dp(6),p);}}
  @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){if(!a.layerEditable())return false;List<FillStyle.Stop> stops=style().ordered(time());FillStyle.Stop best=stops.get(0);for(FillStyle.Stop s:stops)if(Math.abs(x(s.position.at(time()))-e.getX())<Math.abs(x(best.position.at(time()))-e.getX()))best=s;stopId=best.id;down=e.getX();moving=false;getParent().requestDisallowInterceptTouchEvent(true);refresh();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){if(!moving&&Math.abs(e.getX()-down)>ViewConfiguration.get(a).getScaledTouchSlop()){begin();moving=true;}if(moving){double pos=Math.max(0,Math.min(1,(e.getX()-a.dp(14))/Math.max(1f,getWidth()-a.dp(28))));live(()->style().stops.get(stopId).position.set(time(),pos));}return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);if(moving)end(e.getActionMasked()==MotionEvent.ACTION_CANCEL);moving=false;performClick();return true;}return false;}
  @Override public boolean performClick(){super.performClick();return true;}
 }
}
